package com.vibeguard.samples.reports; import java.nio.charset.*; import java.util.*; import java.util.concurrent.*; import org.springframework.core.io.*; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; @RestController @RequestMapping("/api/reports") public class ReportController {private final Map<String,String> reports=new ConcurrentHashMap<>();@PostMapping public ResponseEntity<Map<String,String>> create(@RequestBody Map<String,String> range){String id=UUID.randomUUID().toString();reports.put(id,"metric,value\nsignups,10\nrevenue,250\n");return ResponseEntity.status(201).body(Map.of("id",id));}@GetMapping("/{id}/download") public ResponseEntity<ByteArrayResource> download(@PathVariable String id){String csv=reports.get(id);return csv==null?ResponseEntity.notFound().build():ResponseEntity.ok().header(HttpHeaders.CONTENT_DISPOSITION,"attachment; filename=report.csv").body(new ByteArrayResource(csv.getBytes(StandardCharsets.UTF_8)));} }
